insert into public.courses (id, slug, title, short_description, description, level, category, icon, estimated_duration, position) values
  ('0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', 'fondamentaux', 'Fondamentaux de la cybersécurité', 'Les bases indispensables avant de plonger dans la sécurité informatique.', 'Ce que la cybersécurité protège, les grandes familles de menaces et les acteurs qui défendent nos systèmes. Le point de départ idéal, sans prérequis.', 'debutant', 'Fondamentaux', 'fondamentaux', 32, 10),
  ('c9468857-0122-856c-b60f-5c05e13778a7', 'reseaux', 'Réseaux informatiques', 'Comprendre comment circulent les données pour mieux les protéger.', 'DNS, ports, protocoles et modèle OSI : comprendre comment circulent les données pour repérer ce qui cloche et mieux les protéger.', 'debutant', 'Réseaux', 'reseaux', 41, 20),
  ('776b1633-dd76-67f4-532f-87063a481f11', 'linux', 'Administration Linux', 'Le terminal, les permissions et les commandes essentielles.', 'Le terminal, l’arborescence et les permissions : les gestes Linux qu’utilise chaque jour un analyste ou un administrateur.', 'intermediaire', 'Linux', 'linux', 30, 30),
  ('40abe0c4-0341-1c25-adee-8292a16408cf', 'securite-web', 'Sécurité Web', 'HTTPS, comptes sécurisés et détection du phishing : les bons réflexes du web.', 'HTTPS, gestionnaire de mots de passe, MFA et détection du phishing : les réflexes qui protègent tes comptes et ceux de ton équipe.', 'intermediaire', 'Sécurité Web', 'securite-web', 32, 40),
  ('670158eb-05c8-85b8-e35e-ac2453d632e5', 'pentest-intro', 'Introduction au Pentest', 'Découvre la méthodologie des tests d''intrusion éthiques.', 'Autorisation, périmètre, méthode et rapport : la démarche d’un test d’intrusion éthique, de la lettre de mission à la recommandation.', 'avance', 'Pentest', 'pentest-intro', 38, 50),
  ('86590338-8e6a-9244-4b5b-54cc25a8a9a1', 'analyse-logs', 'Analyse de logs', 'Lire les événements, relier les indices et qualifier une alerte sans conclure trop vite.', 'Lire un journal, corréler des événements et qualifier une alerte sans conclure trop vite : les bases du travail en SOC.', 'intermediaire', 'Détection', 'analyse-logs', 34, 60)
insert into public.course_modules (id, course_id, title, description, position) values
  ('9eb524ae-1b27-a325-539d-bda421c0627e', '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', 'Comprendre la cybersécurité', 'Ce que l’on protège, et contre quoi.', 1),
  ('31387ec3-76c8-0172-1b3a-e2409798e572', '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', 'L’écosystème de la sécurité', 'Qui défend, qui attaque, et avec quels réflexes.', 2),
  ('e5593265-96cd-af22-796d-43f710a7270f', 'c9468857-0122-856c-b60f-5c05e13778a7', 'Les services du réseau', 'DNS, ports et protocoles : ce qui circule vraiment.', 1),
  ('9e470ce9-9d01-ddb0-1a90-ab0335b6f4b9', 'c9468857-0122-856c-b60f-5c05e13778a7', 'Les couches du réseau', 'Lire un échange réseau couche par couche.', 2),
  ('62477308-a201-76f1-057c-f297445d9139', '776b1633-dd76-67f4-532f-87063a481f11', 'Prendre en main Linux', 'Se repérer et se déplacer dans le système de fichiers.', 1),
  ('afc5997d-3502-efa2-3239-290921bbaa77', '776b1633-dd76-67f4-532f-87063a481f11', 'Droits et utilisateurs', 'Qui peut lire, écrire, exécuter — et pourquoi c’est crucial.', 2),
  ('9cd4050a-9697-5bc1-6f15-903217984b6a', '40abe0c4-0341-1c25-adee-8292a16408cf', 'Naviguer en sécurité', 'Ce que HTTPS garantit, et ce qu’il ne garantit pas.', 1),
  ('cac61a27-3cf0-4193-c6f6-e0368abfd2a9', '40abe0c4-0341-1c25-adee-8292a16408cf', 'Protéger ses comptes', 'Mots de passe, MFA et messages piégés.', 2),
  ('b591ac0e-4d89-10bd-4077-7d5aeb7c32c3', '670158eb-05c8-85b8-e35e-ac2453d632e5', 'Cadre et méthode', 'Tester légalement, avec une méthode reproductible.', 1),
  ('27120b00-9922-bac6-f16f-6650ac099377', '670158eb-05c8-85b8-e35e-ac2453d632e5', 'Restitution', 'Transformer une découverte en correction utile.', 2),
  ('3f229e54-4809-d296-89e3-14648080233a', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', 'Lire les journaux', 'Comprendre un événement et relier les indices.', 1),
  ('9bbc731c-3ce3-2024-c67b-c719856c68ac', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', 'Qualifier une alerte', 'Décider, documenter et transmettre.', 2)
insert into public.lessons (id, course_id, module_id, title, summary, content, duration_minutes, xp_reward, position) values
  ('f224ac19-650c-93e5-75f9-1276cc02ae0a', '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', '9eb524ae-1b27-a325-539d-bda421c0627e', 'Qu''est-ce que la cybersécurité ?', 'La cybersécurité désigne l''ensemble des pratiques, technologies et processus conçus pour protéger les systèmes informatiques, les réseaux et les données contre les attaques, les dommages ou les accès non autorisés.', '{"blocks":[{"type":"text","content":"La cybersécurité désigne l''ensemble des pratiques, technologies et processus conçus pour protéger les systèmes informatiques, les réseaux et les données contre les attaques, les dommages ou les accès non autorisés."},{"type":"schema","content":"Confidentialité → protéger les données privées\nIntégrité → garantir que les données ne sont pas altérées\nDisponibilité → assurer l''accès aux services quand on en a besoin"},{"type":"text","content":"Ces trois piliers forment la triade CIA (Confidentiality, Integrity, Availability). Toute décision en sécurité informatique se réfère à l''un ou plusieurs de ces principes."},{"type":"example","content":"Exemple : un ransomware (rançongiciel) viole la disponibilité en chiffrant tes fichiers. Un keylogger viole la confidentialité en capturant tes frappes au clavier."}]}'::jsonb, 10, 40, 1),
  ('3f531e71-da67-19ff-2426-096e0261b189', '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', '9eb524ae-1b27-a325-539d-bda421c0627e', 'Les types de menaces informatiques', 'Les cybermenaces se classifient en plusieurs catégories : malwares, phishing, attaques par déni de service (DoS/DDoS), ingénierie sociale, et exploitation de vulnérabilités logicielles.', '{"blocks":[{"type":"text","content":"Les cybermenaces se classifient en plusieurs catégories : malwares, phishing, attaques par déni de service (DoS/DDoS), ingénierie sociale, et exploitation de vulnérabilités logicielles."},{"type":"schema","content":"Malware : virus, vers, trojans, ransomware, spyware\nPhishing : email frauduleux imitant une entité de confiance\nDDoS : saturation d''un serveur par des millions de requêtes\nIngénierie sociale : manipulation psychologique d''un utilisateur"},{"type":"text","content":"La majorité des attaques réussies exploitent l''humain, pas la technologie. C''est pourquoi la sensibilisation est aussi importante que les outils techniques."},{"type":"example","content":"Exemple réel : le phishing représente plus de 80% des cyberattaques réussies en entreprise selon les rapports annuels de l''ANSSI."}]}'::jsonb, 12, 45, 2),
  ('28d13e07-9a2a-461d-f792-f8e2f439127d', '0f8fe7e2-bf96-3f6f-3f87-19cb1b730438', '31387ec3-76c8-0172-1b3a-e2409798e572', 'Les acteurs de la cybersécurité', 'On distingue plusieurs profils dans l''écosystème de la cybersécurité : les attaquants (black hat), les défenseurs (blue team), les auditeurs offensifs (red team / pentesters) et les chercheurs (white hat).', '{"blocks":[{"type":"text","content":"On distingue plusieurs profils dans l''écosystème de la cybersécurité : les attaquants (black hat), les défenseurs (blue team), les auditeurs offensifs (red team / pentesters) et les chercheurs (white hat)."},{"type":"schema","content":"Red Team (offensif) : simule des attaques pour tester les défenses\nBlue Team (défensif) : détecte, analyse et répond aux incidents\nPurple Team : collaboration Red + Blue pour améliorer la posture globale\nSOC : Security Operations Center — surveillance 24h/24"},{"type":"text","content":"En tant qu''apprenant Cyberpingo, tu vas progressivement maîtriser les deux côtés : comprendre les techniques d''attaque pour mieux défendre."}]}'::jsonb, 10, 40, 1),
  ('b6fc0a07-6799-72eb-8c61-8ffdd153c97e', 'c9468857-0122-856c-b60f-5c05e13778a7', 'e5593265-96cd-af22-796d-43f710a7270f', 'Comprendre le fonctionnement du DNS', 'Le DNS (Domain Name System) traduit les noms de domaine lisibles par les humains, comme cyberpingo.com, en adresses IP compréhensibles par les machines.', '{"blocks":[{"type":"text","content":"Le DNS (Domain Name System) traduit les noms de domaine lisibles par les humains, comme cyberpingo.com, en adresses IP compréhensibles par les machines."},{"type":"schema","content":"Navigateur → Résolveur DNS → Serveur racine → Serveur TLD → Serveur autoritaire → Adresse IP"},{"type":"text","content":"Chaque requête DNS suit une hiérarchie précise. Comprendre cette chaîne est essentiel pour repérer des attaques comme le DNS spoofing."},{"type":"code","content":"dig cyberpingo.com +short\n# Retourne l''adresse IP associée au domaine","language":"bash"},{"type":"example","content":"Exemple concret : lorsque tu tapes une URL, ton ordinateur interroge d''abord son cache local avant de contacter un résolveur DNS."}]}'::jsonb, 12, 50, 1),
  ('84432c64-0d2a-ea1c-ed10-765133451c32', 'c9468857-0122-856c-b60f-5c05e13778a7', 'e5593265-96cd-af22-796d-43f710a7270f', 'Les ports et protocoles réseau', 'Un port réseau identifie un service précis sur une machine.', '{"blocks":[{"type":"text","content":"Un port réseau identifie un service précis sur une machine. Par exemple, le port 443 correspond au HTTPS et le port 22 au SSH."},{"type":"schema","content":"Port 21 → FTP (transfert de fichiers)\nPort 22 → SSH (accès distant sécurisé)\nPort 80 → HTTP (web non chiffré)\nPort 443 → HTTPS (web chiffré)\nPort 3306 → MySQL (base de données)"},{"type":"code","content":"nmap -sV 192.168.1.10\n# Scanne les ports ouverts et détecte les services","language":"bash"},{"type":"text","content":"Les ports inférieurs à 1024 sont dits \"bien connus\" (well-known ports) et nécessitent des privilèges root pour être ouverts. Un service inattendu sur un port inhabituel est souvent le signe d''une compromission."}]}'::jsonb, 15, 60, 2),
  ('9853f10a-9941-0b53-c76a-a1ac142e2bbb', 'c9468857-0122-856c-b60f-5c05e13778a7', '9e470ce9-9d01-ddb0-1a90-ab0335b6f4b9', 'Le modèle OSI en pratique', 'Le modèle OSI (Open Systems Interconnection) décompose les communications réseau en 7 couches.', '{"blocks":[{"type":"text","content":"Le modèle OSI (Open Systems Interconnection) décompose les communications réseau en 7 couches. Chaque couche a une responsabilité précise et communique avec les couches adjacentes."},{"type":"schema","content":"7. Application  → HTTP, FTP, DNS, SMTP\n6. Présentation → Chiffrement, encodage (TLS)\n5. Session      → Établissement de sessions\n4. Transport    → TCP / UDP, ports\n3. Réseau       → IP, routage\n2. Liaison      → MAC, Ethernet, Wi-Fi\n1. Physique     → Câbles, ondes radio"},{"type":"text","content":"En cybersécurité, les attaques ciblent des couches précises : ARP spoofing vise la couche 2, les attaques IP spoofing visent la couche 3, et les injections SQL visent la couche 7."},{"type":"example","content":"Astuce mnémotechnique : \"Please Do Not Touch Steve''s Pet Alligator\" (Physical, Data, Network, Transport, Session, Presentation, Application)."}]}'::jsonb, 14, 55, 1),
  ('517f5de3-280e-7bde-1d63-fcf252ad270e', '776b1633-dd76-67f4-532f-87063a481f11', '62477308-a201-76f1-057c-f297445d9139', 'Naviguer dans le système de fichiers Linux', 'Linux organise tout son système dans une arborescence de répertoires qui part de la racine /.', '{"blocks":[{"type":"text","content":"Linux organise tout son système dans une arborescence de répertoires qui part de la racine /. Contrairement à Windows, il n''existe pas de lettres de lecteur (C:, D:) — tout est monté dans cette arborescence unique."},{"type":"schema","content":"/          → racine du système\n/home      → dossiers personnels des utilisateurs\n/etc       → fichiers de configuration\n/var/log   → journaux système\n/tmp       → fichiers temporaires\n/bin /usr/bin → exécutables système"},{"type":"code","content":"pwd          # Affiche le répertoire courant\nls -la       # Liste tous les fichiers avec permissions\ncd /etc      # Se déplacer dans /etc\nfind / -name ''*.conf'' 2>/dev/null  # Trouver tous les fichiers .conf","language":"bash"},{"type":"text","content":"La commande `find` est très utilisée en pentest pour localiser des fichiers de configuration sensibles. Le redirection `2>/dev/null` cache les erreurs de permission."}]}'::jsonb, 14, 55, 1),
  ('f12a8799-f1b5-972b-9741-2c89918854a5', '776b1633-dd76-67f4-532f-87063a481f11', 'afc5997d-3502-efa2-3239-290921bbaa77', 'Permissions et gestion des utilisateurs', 'Les permissions Linux s''appliquent à trois entités : le propriétaire (user), le groupe (group) et les autres (others).', '{"blocks":[{"type":"text","content":"Les permissions Linux s''appliquent à trois entités : le propriétaire (user), le groupe (group) et les autres (others). Pour chacun : lecture (r=4), écriture (w=2), exécution (x=1)."},{"type":"schema","content":"-rwxr-xr-- 1 alice devs 4096 fichier.sh\n ^^^→ propriétaire : rwx (7)\n    ^^^→ groupe     : r-x (5)\n       ^^^→ autres   : r-- (4)\nPermission octale : 754"},{"type":"code","content":"chmod 750 script.sh     # rwxr-x--- : propriétaire full, groupe lecture+exec\nchown alice:devs fichier # Changer propriétaire et groupe\nsudo su -               # Devenir root\nwhoami                  # Afficher l''utilisateur courant\nid                      # Afficher UID, GID et groupes","language":"bash"},{"type":"text","content":"Un fichier SUID (chmod u+s) s''exécute avec les droits du propriétaire, pas de celui qui le lance. C''est une surface d''attaque classique en privilege escalation."},{"type":"example","content":"Commande de recherche de binaires SUID : find / -perm -4000 -type f 2>/dev/null — très utilisé lors d''un audit de machine Linux."}]}'::jsonb, 16, 65, 1),
  ('eadc6ced-16dc-90ec-e1d1-297bc8b0202b', '40abe0c4-0341-1c25-adee-8292a16408cf', '9cd4050a-9697-5bc1-6f15-903217984b6a', 'HTTPS : ce que le cadenas protège vraiment', 'HTTPS chiffre les échanges entre ton navigateur et le serveur.', '{"blocks":[{"type":"text","content":"HTTPS chiffre les échanges entre ton navigateur et le serveur. Un observateur du réseau ne peut pas lire directement le contenu de cette connexion. Le certificat sert également à vérifier le nom du serveur auquel tu te connectes."},{"type":"text","content":"Un site frauduleux peut lui aussi utiliser HTTPS. Le cadenas ne prouve ni l’honnêteté du vendeur, ni l’absence d’arnaque. Vérifie le nom de domaine exact, la provenance du lien et la cohérence de la demande avant de communiquer des informations."},{"type":"example","content":"Tu reçois un message qui te demande de te connecter à banque-exemple.test. N’utilise pas ce lien : ouvre toi-même l’application ou l’adresse habituelle de ta banque. Les adresses en .test sont réservées aux exemples."}]}'::jsonb, 10, 50, 1),
  ('e17f9e23-37d2-6396-44ae-ec0f2a436175', '40abe0c4-0341-1c25-adee-8292a16408cf', 'cac61a27-3cf0-4193-c6f6-e0368abfd2a9', 'Protéger ses comptes avec un gestionnaire et la MFA', 'Utilise un mot de passe long et unique pour chaque compte.', '{"blocks":[{"type":"text","content":"Utilise un mot de passe long et unique pour chaque compte. Un gestionnaire de mots de passe peut générer et enregistrer ces secrets. Protège son coffre avec une phrase de passe unique, longue et difficile à deviner."},{"type":"text","content":"La double authentification ajoute une seconde preuve. Les clés de sécurité et les passkeys peuvent résister au phishing ; une application d’authentification reste utile si ces options ne sont pas proposées. Conserve les codes de récupération hors de ton appareil principal."},{"type":"example","content":"Plan pratique : sécurise d’abord ta messagerie principale, car elle sert souvent à réinitialiser tes autres comptes. Active la MFA, vérifie les sessions ouvertes et range tes codes de secours."}]}'::jsonb, 12, 50, 1),
  ('fd1598af-3d9d-1412-b123-7b76e96ee6d3', '40abe0c4-0341-1c25-adee-8292a16408cf', 'cac61a27-3cf0-4193-c6f6-e0368abfd2a9', 'Déjouer un message de phishing', 'Un message de phishing cherche à provoquer une action : saisir un secret, payer, ouvrir une pièce jointe ou valider une connexion.', '{"blocks":[{"type":"text","content":"Un message de phishing cherche à provoquer une action : saisir un secret, payer, ouvrir une pièce jointe ou valider une connexion. L’urgence, la peur et les offres inattendues sont des leviers fréquents, mais un message très bien écrit peut aussi être frauduleux."},{"type":"text","content":"Vérifie la demande par un canal indépendant que tu connais déjà. Ne réponds pas au message pour demander une confirmation. Dans une organisation, utilise la procédure de signalement et préserve le message sans diffuser ses pièces jointes."},{"type":"example","content":"« Ton compte sera fermé dans 10 minutes, communique ton code de connexion. » Ne transmets pas de code. Ouvre le service directement et consulte ses notifications officielles."}]}'::jsonb, 10, 50, 2),
  ('2a1cfa1f-1d87-acd1-da42-8da5ab1cd236', '670158eb-05c8-85b8-e35e-ac2453d632e5', 'b591ac0e-4d89-10bd-4077-7d5aeb7c32c3', 'Autorisation et périmètre d’un audit', 'Un test d’intrusion doit reposer sur une autorisation explicite du responsable habilité du système.', '{"blocks":[{"type":"text","content":"Un test d’intrusion doit reposer sur une autorisation explicite du responsable habilité du système. Le périmètre précise les adresses, applications, comptes, horaires et méthodes autorisés. Un système accessible sur Internet n’est pas automatiquement autorisé à être testé."},{"type":"text","content":"Les règles d’engagement prévoient un contact d’urgence, des conditions d’arrêt, la gestion des données et les actions interdites. Demande une clarification écrite dès qu’un doute apparaît. CyberPingo n’autorise pas à tester des systèmes tiers."},{"type":"example","content":"Une application est autorisée, mais son prestataire de paiement ne figure pas au périmètre. N’effectue aucun test chez ce prestataire sans une autorisation distincte."}]}'::jsonb, 12, 50, 1),
  ('c670235e-1bde-3053-414f-91ec83fd3f1e', '670158eb-05c8-85b8-e35e-ac2453d632e5', 'b591ac0e-4d89-10bd-4077-7d5aeb7c32c3', 'Une méthode de test responsable', 'Un audit suit des étapes : cadrage, compréhension de l’application, identification des risques, vérifications contrôlées et restitution.', '{"blocks":[{"type":"text","content":"Un audit suit des étapes : cadrage, compréhension de l’application, identification des risques, vérifications contrôlées et restitution. L’objectif n’est pas de provoquer un incident, mais d’identifier des améliorations de sécurité reproductibles."},{"type":"text","content":"Choisis la preuve la moins intrusive. Note l’heure, les préconditions et le résultat. Arrête-toi si une action menace la disponibilité ou expose des données sensibles hors du périmètre prévu. Travaille dans un laboratoire local pour apprendre les gestes techniques."},{"type":"example","content":"Pour documenter une autorisation mal configurée, utilise deux comptes de test fournis par le propriétaire, jamais le compte d’un client réel."}]}'::jsonb, 14, 50, 2),
  ('71df3ffc-bfe3-4d15-d1de-a8a878beb7ba', '670158eb-05c8-85b8-e35e-ac2453d632e5', '27120b00-9922-bac6-f16f-6650ac099377', 'Rédiger une recommandation utile', 'Un résultat d’audit doit expliquer le problème, les éléments affectés, les préconditions, l’impact et une correction concrète.', '{"blocks":[{"type":"text","content":"Un résultat d’audit doit expliquer le problème, les éléments affectés, les préconditions, l’impact et une correction concrète. La criticité dépend du contexte métier et de la facilité d’exploitation ; elle ne se résume pas au nom d’un outil."},{"type":"text","content":"Le rapport doit être transmis aux destinataires autorisés par un canal adapté. Masque les données personnelles inutiles, limite les secrets dans les captures et définis leur durée de conservation. Un retest vérifie ensuite l’efficacité de la correction."},{"type":"example","content":"Titre : « Contrôle d’accès manquant sur une ressource de test ». Recommandation : vérifier côté serveur que l’utilisateur possède les droits nécessaires à chaque requête, puis ajouter des tests de non-régression."}]}'::jsonb, 12, 50, 1),
  ('f4be91e0-6c7a-5f55-52d6-6df702ba0bb7', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', '3f229e54-4809-d296-89e3-14648080233a', 'Lire un événement dans un journal', 'Un journal enregistre des événements produits par un système ou une application.', '{"blocks":[{"type":"text","content":"Un journal enregistre des événements produits par un système ou une application. Pour interpréter une ligne, repère l’horodatage, la source, l’action, son résultat et les identifiants utiles. Un message d’erreur isolé ne suffit pas à conclure à une attaque."},{"type":"text","content":"Vérifie le fuseau horaire, la synchronisation des horloges et le format des champs. Des heures incohérentes rendent les rapprochements difficiles. Les journaux peuvent contenir des données personnelles : n’y enregistre jamais de mot de passe ou de jeton complet."},{"type":"example","content":"Événement fictif : 2026-09-01T08:15:00Z source=portail action=connexion utilisateur=test resultat=echec. Le suffixe Z indique UTC. La ligne ne dit pas, à elle seule, pourquoi la connexion a échoué."}]}'::jsonb, 10, 50, 1),
  ('4a4aeb58-f129-be66-8bb7-4fd41cf83da0', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', '3f229e54-4809-d296-89e3-14648080233a', 'Relier les événements sans conclure trop vite', 'La corrélation rapproche des événements sur une période, une source ou un compte.', '{"blocks":[{"type":"text","content":"La corrélation rapproche des événements sur une période, une source ou un compte. Plusieurs échecs suivis d’une réussite peuvent justifier une vérification. Compare cette séquence à l’activité habituelle et aux informations d’autres systèmes."},{"type":"text","content":"Une adresse IP ne représente pas forcément une seule personne. Un réseau d’entreprise, un VPN ou un opérateur mobile peut partager une adresse entre plusieurs utilisateurs. Formule une hypothèse et cherche des éléments qui pourraient aussi la contredire."},{"type":"example","content":"Exercice fictif : 08:15 échec, 08:16 échec, 08:17 réussite, 08:18 changement de MFA. Cette séquence mérite un examen du compte, sans être automatiquement une compromission."}]}'::jsonb, 12, 50, 2),
  ('7f098d36-6bd9-39c9-f2a9-40753f8c514f', '86590338-8e6a-9244-4b5b-54cc25a8a9a1', '9bbc731c-3ce3-2024-c67b-c719856c68ac', 'Qualifier une alerte et documenter la suite', 'Le triage consiste à comprendre une alerte, sa fiabilité et son impact potentiel.', '{"blocks":[{"type":"text","content":"Le triage consiste à comprendre une alerte, sa fiabilité et son impact potentiel. Identifie le système concerné, sa criticité, l’étendue observée et les éléments manquants. Préserve les traces et suis le processus d’escalade de ton organisation."},{"type":"text","content":"Documente les faits séparément des hypothèses. Une action de confinement peut interrompre un service : elle doit suivre les autorisations et procédures prévues. Après traitement, note les enseignements pour améliorer la détection et réduire les faux positifs."},{"type":"example","content":"Note de triage : « Fait : cinq échecs puis une réussite sur le compte de test. Hypothèse : tentative de connexion non autorisée. À vérifier : appareil utilisé, contexte utilisateur et changement de MFA. »"}]}'::jsonb, 12, 50, 1)
