insert into public.quiz_questions (id, quiz_id, position, question_type, prompt, explanation, difficulty, xp_reward) values
  ('40d2e2f4-21e8-9d7c-7f4c-3508395a7354', 'd0948983-d4f6-c304-99a8-0a6ff76b4144', 1, 'single_choice', 'La confidentialité consiste à…', 'La confidentialité protège l’accès aux informations.', 'facile', 30),
  ('e19b3241-f649-851a-8400-c3bc67f3ec69', 'd0948983-d4f6-c304-99a8-0a6ff76b4144', 2, 'single_choice', 'Une blue team travaille principalement sur…', 'Elle protège les systèmes et traite les événements de sécurité.', 'facile', 30),
  ('02a8f938-840e-38fc-3085-2c2bde090beb', '7cf99ab0-cf82-6b7d-f66e-72a128fb53b7', 1, 'single_choice', 'À quoi sert principalement le DNS ?', 'Le DNS agit comme un annuaire : il convertit un nom de domaine lisible en une adresse IP utilisable par les machines.', 'facile', 27),
  ('46dbc263-3789-9e86-0502-4bbb423c451c', '7cf99ab0-cf82-6b7d-f66e-72a128fb53b7', 2, 'true_false', 'Le DNS spoofing consiste à rediriger un utilisateur vers un faux site.', 'Le DNS spoofing falsifie les réponses DNS pour rediriger la victime vers un site malveillant qui imite le site légitime.', 'facile', 27),
  ('a94b1561-ae6c-5726-4574-0dfb5ae5ad8f', '7cf99ab0-cf82-6b7d-f66e-72a128fb53b7', 3, 'single_choice', 'Quelle commande permet d''interroger un enregistrement DNS ?', 'La commande dig interroge directement les serveurs DNS et affiche les enregistrements associés à un domaine.', 'facile', 26),
  ('c2f3bbf5-291e-99a1-9048-59a2c6c231f9', '677b9339-0753-a465-bd39-da5e93d9eb62', 1, 'single_choice', 'La permission r permet de…', 'r signifie read, donc lecture.', 'moyen', 30),
  ('1183e4e0-7efc-b599-6dda-e02b13d57008', '677b9339-0753-a465-bd39-da5e93d9eb62', 2, 'single_choice', 'Pourquoi limiter les permissions ?', 'Chaque utilisateur ou processus doit disposer uniquement des droits nécessaires.', 'moyen', 30),
  ('869908dc-03b1-9de3-d182-819686242c3d', '4cdf48d8-374f-658c-08ae-c38374e0affb', 1, 'single_choice', 'Que protège principalement HTTPS ?', 'HTTPS protège le transport des données, pas les intentions de celui qui exploite le site.', 'moyen', 30),
  ('c9f48fa1-4af2-fa55-1a49-7d669a585ffb', '4cdf48d8-374f-658c-08ae-c38374e0affb', 2, 'single_choice', 'Un site avec un cadenas peut-il être frauduleux ?', 'Les sites frauduleux peuvent obtenir des certificats valides. Le domaine et le contexte restent essentiels.', 'moyen', 30),
  ('7f565638-5c5e-5201-5ba9-c3ffd0ce1b6f', '31bdb56a-1086-1c89-2b98-86ea3e1c69fc', 1, 'single_choice', 'Quelle stratégie limite les conséquences d’une fuite ?', 'La réutilisation permet à une fuite sur un service de compromettre les autres.', 'moyen', 30),
  ('d0572fe9-46dc-504e-418f-1ae46e9ea0b9', '31bdb56a-1086-1c89-2b98-86ea3e1c69fc', 2, 'single_choice', 'Où conserver les codes de récupération ?', 'Ces codes doivent rester secrets et accessibles si ton appareil principal est perdu.', 'moyen', 30),
  ('40e940f8-ee6b-935c-f1fc-8827d447f272', '8db632ea-1200-23d7-0e6f-af71f05017e0', 1, 'single_choice', 'Quel est le meilleur moyen de vérifier une demande suspecte ?', 'L’auteur du message peut répondre lui-même et copier un logo. Un canal connu limite ce risque.', 'moyen', 30),
  ('5624196e-e91d-4b53-821f-44824b92ae48', '8db632ea-1200-23d7-0e6f-af71f05017e0', 2, 'single_choice', 'Un code de connexion demandé par un inconnu doit être…', 'Un code de connexion est un secret, même s’il n’est valable que quelques secondes.', 'moyen', 30),
  ('78ce53cc-6741-6ec3-8f45-34d45542aa69', 'e848028e-bd11-7260-84e5-21a8646e7001', 1, 'single_choice', 'Avant tout test, il faut…', 'L’autorisation et le périmètre établissent les limites du travail.', 'difficile', 30),
  ('9894f937-76ea-e26f-fab0-8e068f73112b', 'e848028e-bd11-7260-84e5-21a8646e7001', 2, 'single_choice', 'Une cible inconnue apparaît pendant l’audit. Que faire ?', 'Ne déduis pas une autorisation à partir d’une découverte technique.', 'difficile', 30),
  ('42ad6bb9-9dbf-529e-5936-55ecbc2eaf0e', '47c81c76-cf50-e187-c00e-281d942f15cc', 1, 'single_choice', 'Quelle preuve est préférable ?', 'Une preuve contrôlée permet de comprendre le risque sans causer de dommages inutiles.', 'difficile', 30),
  ('b99a7785-ae97-8630-bccd-6fdf131dd89a', '47c81c76-cf50-e187-c00e-281d942f15cc', 2, 'single_choice', 'Si le service devient instable pendant un test…', 'La sécurité opérationnelle et les conditions d’arrêt priment.', 'difficile', 30),
  ('cc6954ca-5112-ba28-e7b3-e625f27283e5', '254cd55e-56df-0aba-acfd-958860ad9e29', 1, 'single_choice', 'Une recommandation utile contient…', 'Le destinataire doit pouvoir comprendre, prioriser et corriger le problème.', 'difficile', 30),
  ('c4b88637-d514-3672-a576-c0a4135a45ee', '254cd55e-56df-0aba-acfd-958860ad9e29', 2, 'single_choice', 'À quoi sert un retest ?', 'Le retest confirme que le problème est corrigé et recherche les régressions liées.', 'difficile', 30),
  ('d800eb2d-238b-6ea8-30e1-e5b8425f3f07', '4db60cf4-a4f4-fe10-b1cc-1c2422f589fc', 1, 'single_choice', 'Quel champ aide à ordonner les événements ?', 'L’horodatage donne une référence temporelle, à condition de vérifier le fuseau et l’horloge.', 'moyen', 30),
  ('472e9583-a0e1-7f61-0d95-a818a7507f43', '4db60cf4-a4f4-fe10-b1cc-1c2422f589fc', 2, 'single_choice', 'Un seul échec de connexion prouve-t-il une attaque ?', 'Une faute de frappe ou un problème technique peuvent aussi produire un échec.', 'moyen', 30),
  ('d738a356-a66b-fa5f-519f-e41e97a72bd1', '3f92b481-ca4c-331d-5172-db5525fc2c9f', 1, 'single_choice', 'Pourquoi consulter plusieurs sources ?', 'Le contexte évite de transformer une coïncidence en certitude.', 'moyen', 30),
  ('02068ff8-38ab-c358-71c5-9cc4527977f9', '3f92b481-ca4c-331d-5172-db5525fc2c9f', 2, 'single_choice', 'Une même adresse IP signifie…', 'Des infrastructures partagées peuvent utiliser une même adresse publique.', 'moyen', 30),
  ('9f32f28c-37e8-ae91-0db0-15b456795d51', '5e613221-df28-f5a1-2889-5b73d634d457', 1, 'single_choice', 'Une note de triage doit distinguer…', 'Cette distinction aide un autre analyste à reprendre l’enquête sans confondre supposition et preuve.', 'moyen', 30),
  ('de1e09c1-1b24-368c-b62b-833f433a5ac2', '5e613221-df28-f5a1-2889-5b73d634d457', 2, 'single_choice', 'Avant un confinement susceptible d’interrompre un service…', 'La réponse doit être proportionnée, autorisée et documentée.', 'moyen', 30)
