insert into public.labs (id, slug, title, description, category, difficulty, xp_reward, objectives, hints, terminal_lines, flag_placeholder, position) values
  ('631b4d58-280a-81fe-824d-b5e78d2f8215', 'decouvrir-les-ports-reseau', 'Découvrir les ports réseau', 'Analyse une machine cible fictive et identifie les ports ouverts à l''aide d''un terminal simulé.', 'reseau', 'debutant', 100, array['Lancer un scan de ports sur la machine cible', 'Identifier le service tournant sur le port 22', 'Soumettre le nom du service en guise de réponse']::text[], array['La commande nmap est utilisée pour scanner les ports.', 'Le port 22 est traditionnellement associé à un protocole d''accès distant sécurisé.']::text[], array['$ nmap -sV 10.10.10.42', 'PORT     STATE  SERVICE   VERSION', '22/tcp   open   ssh       OpenSSH 8.2', '80/tcp   open   http      nginx 1.18.0', '443/tcp  open   https     nginx 1.18.0']::text[], 'Nom du service sur le port 22', 10),
  ('631e3796-35dd-1fd3-07aa-b6c76df5ab15', 'premiers-pas-en-osint', 'Premiers pas en OSINT', 'Retrouve une information publique à partir d''indices simulés, sans jamais cibler une vraie personne.', 'osint', 'debutant', 80, array['Explorer les métadonnées d''un document fictif', 'Identifier le logiciel utilisé pour le créer']::text[], array['Les métadonnées se trouvent souvent dans les propriétés du fichier.']::text[], array['$ exiftool rapport_fictif.pdf', 'Producer      : LibreOffice 7.4', 'Creator       : agent-formation-01']::text[], 'Logiciel utilisé pour créer le document', 20),
  ('7e4e8f2b-919a-2984-dcf8-87ab8deb59ab', 'permissions-linux', 'Comprendre les permissions Linux', 'Ajuste les permissions d''un fichier simulé pour sécuriser un serveur pédagogique.', 'linux', 'debutant', 90, array['Lister les permissions actuelles', 'Retirer l''accès en écriture aux autres utilisateurs']::text[], array['La commande chmod modifie les permissions d''un fichier.', 'La permission 644 donne rw-r--r--.']::text[], array['$ ls -l config.env', '-rwxrwxrwx 1 root root 220 config.env']::text[], 'Commande chmod à utiliser', 30),
  ('c1180ec0-8fcc-d254-8566-7ac3b8e4c804', 'chiffrement-cesar', 'Casser un chiffrement de César', 'Décode un message chiffré avec un décalage simple pour comprendre les bases de la cryptographie.', 'cryptographie', 'debutant', 70, array['Identifier le décalage utilisé', 'Déchiffrer le message']::text[], array['Essaie plusieurs décalages entre 1 et 25.', 'Le décalage utilisé ici est 13 (ROT13).']::text[], array['Message chiffré : Pbqr Fnyhgngvbany']::text[], 'Message déchiffré', 40),
  ('920bf638-7e77-ab28-3383-5ac0764d31b7', 'injection-sql-basique', 'Repérer une injection SQL', 'Analyse un formulaire de connexion fictif vulnérable pour comprendre le principe d''une injection SQL.', 'web', 'intermediaire', 120, array['Identifier le champ vulnérable', 'Proposer une entrée qui contourne l''authentification']::text[], array['Une requête SQL mal filtrée peut être manipulée avec des guillemets et OR.', 'Le classique : '' OR ''1''=''1']::text[], array['POST /login', 'username=admin'' OR ''1''=''1', 'password=anything']::text[], 'Entrée qui exploite la faille', 50),
  ('3069b696-d65e-f568-efea-12ca4f1a1010', 'hygiene-mots-de-passe', 'Auditer l''hygiène des mots de passe', 'Évalue une liste de mots de passe fictifs et identifie les plus vulnérables.', 'securite', 'debutant', 60, array['Repérer les mots de passe trop courts ou communs']::text[], array['Un bon mot de passe combine longueur et diversité de caractères.', 'Les mots du dictionnaire sont faibles.']::text[], array['azerty123', 'P#7mK!q2Lx9$', 'motdepasse']::text[], 'Le mot de passe le plus faible', 60)
